package br.com.ajudamutua.security;
import br.com.ajudamutua.model.*; import br.com.ajudamutua.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.Instant; import java.util.UUID;
@Configuration @Profile("dev")
public class DevDataConfig {
 @Bean CommandLineRunner demoUsers(AppUserRepository users,MemberRepository members,PasswordEncoder encoder){return args->{create(users,members,encoder,"admin@demo.local","Admin Demo",UserRole.ADMIN,null); create(users,members,encoder,"analyst@demo.local","Analista Demo",UserRole.ANALYST,null); create(users,members,encoder,"approver1@demo.local","Aprovador 1",UserRole.APPROVER,null); create(users,members,encoder,"approver2@demo.local","Aprovador 2",UserRole.APPROVER,null); create(users,members,encoder,"auditor@demo.local","Auditor Demo",UserRole.AUDITOR,null); if(users.findByEmailIgnoreCase("member@demo.local").isEmpty()){var m=members.save(new Member(UUID.randomUUID(),"Membro Demo","member@demo.local",MemberStatus.ACTIVE,Instant.now().minus(java.time.Duration.ofDays(180)))); users.save(new AppUser(UUID.randomUUID(),"member@demo.local",encoder.encode("Demo12345!"),UserRole.MEMBER,m.getId(),true,Instant.now()));}};}
 private void create(AppUserRepository users,MemberRepository members,PasswordEncoder encoder,String email,String name,UserRole role,UUID memberId){if(users.findByEmailIgnoreCase(email).isEmpty()) users.save(new AppUser(UUID.randomUUID(),email,encoder.encode("Demo12345!"),role,memberId,true,Instant.now()));}
}
